cd /workspaces/ai-agent-llms
echo "=== hashes in corpus/task-a-v3 annotation ==="
git tag -l --format='%(contents)' corpus/task-a-v3 | grep -cE '[0-9a-f]{32}\.dir' || echo "0 — NO HASHES"
echo "=== v3 corpus hashes from dvc.lock ==="
.venv/bin/python -c "
import yaml
d=yaml.safe_load(open('dvc.lock'))
want={'task_a_sft_generate','task_a_sft_generate_voice','task_a_sft_clean','task_a_sft_splits'}
for n,s in d['stages'].items():
    if n in want:
        for e in s.get('outs',[]):
            print(f\"{e['path']:42s} {e.get('md5')}  nfiles={e.get('nfiles')}  size={e.get('size')}\")
"

